using UnityEngine;
using UnityEditor;
using System.IO;
using ConRoi.Investigation.V36;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r102/conclusion-ui-profile");
            s.OpenPage("conclusions");
            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/conclusion-ui-before.png");
            r.Log("Private conclusion UI fixture; API opens page only");
        }
    }
}

